from sources import load_source
from checks import normalize

url = "https://en.wikipedia.org/wiki/Hallucination_(artificial_intelligence)"
span = ("In the field of artificial intelligence (AI), a hallucination or artificial "
        "hallucination (also called bullshitting,[1][2] confabulation,[3] delusion,[4] "
        "or mirage[5]) is a response generated by AI that contains false or misleading "
        "information presented as fact.[6]")

src = normalize(load_source(url))
sp = normalize(span)

n = 10
while n <= len(sp) and sp[:n] in src:
    n += 1
print("matches up to:", n - 1, "of", len(sp))

start = src.find(sp[:20])
if start == -1:
    print("first 20 chars not even found")
else:
    print("SPAN :", sp[max(0, n - 60): n + 40])
    print("STORE:", src[start + max(0, n - 60): start + n + 40])